// The second fence for Perro's email (the first is perro/mail.py). Perro may
// write to one person at a time, from a short list kept here only as SHA-256
// hashes of the addresses (this file is in a public repo), at most DAILY a day.
// The message itself is built here, so nothing but these headers can go out.
const ALLOWED = ["261682eabf66e077a16962386cdd869a5ed3fa395ed03b81b48ba11ad218d58d", "3d9a1a17ecdbd8a0ca4274e322bf93b0b14d52fbd5c28dca908f45250416a102", "635a0ed5736e9a98c3c5dbf8aafb553193cea19bae1998955f93d472848fe691", "9fc8937fc21a846eca9dd4e8a2719a9d3e4380ebebf4875a8422c5726a44ed25", "c251b97316bff2051229866ce97f4dcbda4f023df867ef81a23803398678c251", "eaf0a0f4af18ad0ff741ba617a21e0d714dbc54488fdca7347ab5034a773da83", "ee928e056e831d62d6ab92d3312c80edd7eb6d890feb3b1ce0f19361c6d9b56d"];
const DAILY = 30;
const FIELDS = ['to', 'bcc', 'subject', 'body', 'threadId', 'inReplyTo'];
const ADDRESS = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
const j = $input.first().json;
const b = j.body || {};
const refuse = (why) => [{ json: { refused: why } }];

if (typeof b !== 'object' || Array.isArray(b)) return refuse('the body must be an object');
for (const k of Object.keys(b)) if (!FIELDS.includes(k)) return refuse('unexpected field ' + k);
if (typeof b.to !== 'string' || !ADDRESS.test(b.to)) return refuse('to must be one address');
if (!ALLOWED.includes(j.toHash)) return refuse('that address is not on the list');
if (b.bcc !== undefined) {
  if (typeof b.bcc !== 'string' || !ADDRESS.test(b.bcc)) return refuse('bcc must be one address');
  if (!ALLOWED.includes(j.bccHash)) return refuse('the bcc address is not on the list');
}
if (typeof b.subject !== 'string' || !b.subject || b.subject.length > 200 || /[\x00-\x1f\x7f]/.test(b.subject))
  return refuse('the subject must be one line, up to 200 characters');
if (typeof b.body !== 'string' || !b.body || b.body.length > 20000) return refuse('the body must be 1 to 20000 characters');
if (b.threadId !== undefined && (typeof b.threadId !== 'string' || !/^[0-9a-f]{6,40}$/.test(b.threadId)))
  return refuse('bad threadId');
if (b.inReplyTo !== undefined && (typeof b.inReplyTo !== 'string' || !/^<[^<>\s]{3,300}>$/.test(b.inReplyTo)))
  return refuse('bad inReplyTo');

const seen = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (seen.day !== today) { seen.day = today; seen.count = 0; }
if (seen.count >= DAILY) return refuse('the daily limit is reached');
seen.count += 1;

const b64 = (t) => Buffer.from(t, 'utf8').toString('base64');
const headers = ['To: ' + b.to];
if (b.bcc) headers.push('Bcc: ' + b.bcc);
headers.push('Subject: =?UTF-8?B?' + b64(b.subject) + '?=', 'MIME-Version: 1.0',
             'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64');
if (b.inReplyTo) headers.push('In-Reply-To: ' + b.inReplyTo, 'References: ' + b.inReplyTo);
const text = b64(b.body.replace(/\r?\n/g, '\r\n')).replace(/(.{76})/g, '$1\r\n');
const raw = Buffer.from(headers.join('\r\n') + '\r\n\r\n' + text, 'utf8').toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const send = { raw };
if (b.threadId) send.threadId = b.threadId;
return [{ json: { send } }];
